import Foundation
import MLXLMCommon
import Testing
import Tokenizers

@testable import ExperimentKit
@testable import SteeringKit

/// Cross-engine golden RENDER fixtures for BOTH model families.
///
/// `prompts/fixtures/render/*.json` are committed goldens generated by the
/// AUTHORITATIVE Python engine (`prompts/fixtures/render/generate.py`, via the
/// server venv's `transformers` — see the README there). This suite replays
/// the recorded inputs through the SAME Swift path the run loop uses
/// (`ExperimentTasks.userInput` → `DefaultMessageGenerator` →
/// `tokenizer.applyChatTemplate(messages:tools:additionalContext:)`, exactly
/// what mlx-swift-lm's `LLMUserInputProcessor.prepare` executes) and asserts:
///
/// - **token-id parity**: Swift's token ids equal the Python goldens
///   byte-for-byte (`applyChatTemplate` never materializes the rendered
///   string publicly, so ids ARE the operational render on this engine);
/// - **string parity** via decode round-trip: `decode(tokens:)` of the Swift
///   ids must reproduce the Python `rendered` string byte-for-byte;
/// - **bosCount**: the leading-BOS count matches the recorded tripwire value
///   (Gemma exactly 1 with AND without a system prompt; Qwen 0).
///
/// Tokenizers load from the local HF cache snapshot (no network, no GPU).
/// When a model's tokenizer is not cached the test SKIPS LOUDLY (printed
/// message naming the model + early return) — never a silent pass.
///
/// KNOWN, DELIBERATELY-PINNED DIVERGENCE (`raw_completion` fixtures): the
/// Python engine tokenizes rawCompletion text with NO chat template and
/// tokenizer-default special tokens; the Swift engine's
/// `UserInput(prompt: .text(...))` is wrapped in a user chat turn by
/// `LLMUserInputProcessor` (and, for Qwen, without the
/// `enable_thinking=false` context). `rawCompletionDivergence` below pins
/// both behaviors and fails loudly if either engine changes. See the fixture
/// README ("Known cross-engine divergence").
@Suite struct GoldenRenderFixtureTests {

    // MARK: - Fixture schema (mirror of generate.py)

    struct Fixture: Decodable {
        let family: String
        let modelID: String
        let caseName: String
        let inputs: Inputs
        let rendered: String
        let tokenIDs: [Int]
        let promptTokenCount: Int
        let bosCount: Int
        let bosTokenID: Int?

        enum CodingKeys: String, CodingKey {
            case family, modelID, inputs, rendered, tokenIDs
            case promptTokenCount, bosCount, bosTokenID
            case caseName = "case"
        }
    }

    struct Inputs: Decodable {
        let api: String
        let prompt: String?
        let promptMode: String?
        let systemPrompt: String?
        let qwenThinkingEnabled: Bool?
        let messages: [TurnMessage]?
        let text: String?
        /// Assistant-prefix continuation fixtures (`chat_prefill_continue`):
        /// the golden is transformers' own `continue_final_message` render.
        let continueFinalMessage: Bool?
        /// Scripted-transcript study fixtures (`study_transcript`): the
        /// pinned transcript rendered by `render_transcript` — the recorded
        /// `systemPrompt` is a DECOY the transcript's own system turn must
        /// replace.
        let transcript: [TurnMessage]?
    }

    struct TurnMessage: Decodable {
        let role: String
        let content: String
        /// Provenance flag on researcher-authored assistant turns
        /// (`chat_seeded_assistant` fixtures). Rendering must IGNORE it — the
        /// golden was generated from the flagged history and asserted equal
        /// to the flag-stripped twin, so passing these turns through the
        /// ordinary assistant mapping below IS the byte-identity claim.
        let seeded: Bool?
    }

    // MARK: - Locating fixtures and cached tokenizers

    /// Repo root derived from this file's compile-time path (same anchor as
    /// `RepEReaderTests`).
    private static var repoRoot: URL {
        URL(filePath: #filePath)  // …/Tests/ExperimentKitTests/GoldenRenderFixtureTests.swift
            .deletingLastPathComponent()
            .deletingLastPathComponent()
            .deletingLastPathComponent()
    }

    private static var fixtureDirectory: URL {
        repoRoot.appending(components: "prompts", "fixtures", "render")
    }

    private static func loadFixtures() throws -> [Fixture] {
        let files = try FileManager.default.contentsOfDirectory(
            at: fixtureDirectory, includingPropertiesForKeys: nil
        ).filter { $0.pathExtension == "json" }.sorted { $0.path < $1.path }
        return try files.map {
            try JSONDecoder().decode(Fixture.self, from: Data(contentsOf: $0))
        }
    }

    /// All model ids appearing in the committed fixtures (fp repos AND the
    /// MLX repos the Swift engine actually loads).
    private static var fixtureModelIDs: [String] {
        guard let fixtures = try? loadFixtures() else { return [] }
        var seen = Set<String>()
        return fixtures.compactMap { seen.insert($0.modelID).inserted ? $0.modelID : nil }
    }

    /// Local HF cache snapshot for a model id, or nil when not cached.
    private static func cachedSnapshot(for modelID: String) -> URL? {
        let repo = "models--" + modelID.replacingOccurrences(of: "/", with: "--")
        let base = FileManager.default.homeDirectoryForCurrentUser
            .appending(components: ".cache", "huggingface", "hub", repo)
        guard
            let ref = try? String(
                contentsOf: base.appending(components: "refs", "main"),
                encoding: .utf8)
        else { return nil }
        let snapshot = base.appending(
            components: "snapshots",
            ref.trimmingCharacters(in: .whitespacesAndNewlines))
        var isDirectory: ObjCBool = false
        guard
            FileManager.default.fileExists(
                atPath: snapshot.path, isDirectory: &isDirectory),
            isDirectory.boolValue
        else { return nil }
        return snapshot
    }

    private static func leadingBOSCount(_ ids: [Int], bosTokenID: Int?) -> Int {
        guard let bosTokenID else { return 0 }
        var count = 0
        for id in ids {
            guard id == bosTokenID else { break }
            count += 1
        }
        return count
    }

    // MARK: - Guard: the goldens themselves

    /// The committed goldens must exist and span both families — an empty or
    /// half-missing fixture directory is a failure, never a skip.
    @Test func fixtureInventorySpansBothFamilies() throws {
        let fixtures = try Self.loadFixtures()
        #expect(!fixtures.isEmpty, "no golden render fixtures in \(Self.fixtureDirectory.path)")
        let families = Set(fixtures.map(\.family))
        #expect(
            families.isSuperset(of: ["qwen", "gemma"]),
            "golden coverage must span both families, found \(families)")
    }

    // MARK: - The parity claim (chatAssistant + multi-turn + reader)

    /// Token-id AND decode-string parity against the Python goldens, per
    /// model. Loud skip (printed, named) when the tokenizer isn't cached.
    @Test(arguments: fixtureModelIDs)
    func goldenRenderParity(modelID: String) async throws {
        guard let snapshot = Self.cachedSnapshot(for: modelID) else {
            print(
                "SKIP GoldenRenderFixtureTests.goldenRenderParity(\(modelID)): "
                    + "tokenizer not in local HF cache — cross-engine render "
                    + "parity for this model NOT verified on the Swift side")
            return
        }
        let tokenizer = try await AutoTokenizer.from(modelFolder: snapshot)
        let fixtures = try Self.loadFixtures().filter { $0.modelID == modelID }
        #expect(!fixtures.isEmpty, "no fixtures for \(modelID)")

        for fixture in fixtures {
            let swiftIDs: [Int]
            switch fixture.inputs.api {
            case "render" where fixture.inputs.promptMode == "chatAssistant":
                // The exact run-loop path: ExperimentTasks.userInput →
                // DefaultMessageGenerator → applyChatTemplate(messages:tools:
                // additionalContext:) — what LLMUserInputProcessor.prepare does.
                let input = ExperimentTasks.userInput(
                    prompt: fixture.inputs.prompt ?? "",
                    modelID: modelID,
                    promptMode: .chatAssistant,
                    systemPrompt: fixture.inputs.systemPrompt,
                    qwenThinkingEnabled: fixture.inputs.qwenThinkingEnabled ?? false)
                let messages = DefaultMessageGenerator().generate(from: input)
                swiftIDs = try tokenizer.applyChatTemplate(
                    messages: messages, tools: input.tools,
                    additionalContext: input.additionalContext)

            case "render_messages" where fixture.inputs.continueFinalMessage == true:
                // Assistant-prefix continuation ("prefill"): the Swift
                // sentinel-mirror of transformers' continue_final_message
                // must reproduce the Python golden byte-for-byte — the
                // render ends exactly at the seeded prefix (no end-of-turn,
                // no generation prompt appended).
                let turns = (fixture.inputs.messages ?? []).map {
                    ExperimentTasks.ChatTurn(
                        role: $0.role == "assistant" ? .assistant : .user,
                        text: $0.content,
                        seeded: $0.seeded ?? false)
                }
                let render = try ExperimentTasks.continuationRender(
                    tokenizer: tokenizer,
                    turns: turns,
                    modelID: modelID,
                    systemPrompt: fixture.inputs.systemPrompt,
                    qwenThinkingEnabled: fixture.inputs.qwenThinkingEnabled ?? false)
                #expect(
                    render.text == fixture.rendered,
                    """
                    \(fixture.caseName) [\(modelID)]: Swift continuation render \
                    is not byte-identical to transformers' own \
                    continue_final_message render.
                    python: \(fixture.rendered.debugDescription)
                    swift:  \(render.text.debugDescription)
                    """)
                let prefix = turns.last?.text ?? ""
                #expect(
                    render.text.hasSuffix(prefix),
                    Comment(
                        rawValue: "\(fixture.caseName) [\(modelID)]: continuation "
                            + "render must end exactly at the seeded assistant prefix"))
                swiftIDs = render.tokenIDs

            case "render_messages":
                // Multi-turn twin of the server's render_messages: Gemma has
                // no system role (system text folds into the FIRST user turn),
                // Qwen gets a leading system role + enable_thinking context.
                // NOTE: the Swift interactive chat surface (ChatService →
                // ChatSession) folds the Gemma system text into EVERY user
                // turn, not just the first — this test pins the template/
                // tokenizer layer on the server's transcript convention; the
                // ChatService divergence is reported in the fixture README.
                // Seeded assistant turns (`chat_seeded_assistant`) flow
                // through the SAME `.assistant` mapping as real ones — the
                // provenance flag must be invisible to the template, so a
                // passing byte comparison here IS the "indistinguishable to
                // the model" claim for this engine.
                var chat: [Chat.Message] = []
                let system = fixture.inputs.systemPrompt?
                    .trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
                var pendingSystemFold = modelID.lowercased().contains("gemma")
                    && !system.isEmpty
                if !system.isEmpty, !modelID.lowercased().contains("gemma") {
                    chat.append(.system(system))
                }
                for turn in fixture.inputs.messages ?? [] {
                    switch turn.role {
                    case "user":
                        if pendingSystemFold {
                            chat.append(.user(system + "\n\n" + turn.content))
                            pendingSystemFold = false
                        } else {
                            chat.append(.user(turn.content))
                        }
                    case "assistant":
                        chat.append(.assistant(turn.content))
                    default:
                        Issue.record(
                            "fixture \(fixture.caseName): unexpected role \(turn.role)")
                    }
                }
                let messages = DefaultMessageGenerator().generate(messages: chat)
                swiftIDs = try tokenizer.applyChatTemplate(
                    messages: messages, tools: nil,
                    additionalContext: ExperimentTasks.qwenContext(
                        modelID: modelID,
                        qwenThinkingEnabled: fixture.inputs.qwenThinkingEnabled ?? false))

            case "render_transcript":
                // Scripted-transcript study items: the STUDY run loop's own
                // dispatch (`studyUserInput` → `transcriptMessages`) through
                // the same DefaultMessageGenerator → applyChatTemplate path
                // `container.prepare` executes. The fixture's systemPrompt is
                // a decoy the transcript's own system turn must REPLACE — a
                // leak fails the byte comparison below.
                let turns = (fixture.inputs.transcript ?? []).map {
                    ExperimentTasks.TranscriptTurn(role: $0.role, content: $0.content)
                }
                let input = try ExperimentTasks.studyUserInput(
                    text: "",
                    transcript: turns,
                    modelID: modelID,
                    promptMode: .chatAssistant,
                    systemPrompt: fixture.inputs.systemPrompt,
                    qwenThinkingEnabled: fixture.inputs.qwenThinkingEnabled ?? false)
                let messages = DefaultMessageGenerator().generate(from: input)
                swiftIDs = try tokenizer.applyChatTemplate(
                    messages: messages, tools: input.tools,
                    additionalContext: input.additionalContext)

            case "render_reader":
                // Swift twin of render_reader + the extractor's tokenization
                // (ConceptExtractor uses encode(text:) — special tokens per
                // tokenizer default, single tokenizer-added BOS).
                let scaffold = try RepEReader.renderReaderScaffold(
                    fixture.inputs.text ?? "", modelID: modelID)
                #expect(
                    scaffold == fixture.rendered,
                    "\(fixture.caseName) [\(modelID)]: reader scaffold string drifted")
                swiftIDs = tokenizer.encode(text: scaffold)

            case "render" where fixture.inputs.promptMode == "rawCompletion":
                continue  // covered by rawCompletionDivergence below

            default:
                Issue.record(
                    "fixture \(fixture.caseName): unknown inputs.api \(fixture.inputs.api)")
                continue
            }

            #expect(
                swiftIDs == fixture.tokenIDs,
                """
                \(fixture.caseName) [\(modelID)]: Swift token ids diverge from \
                the Python golden (swift \(swiftIDs.count) tokens, golden \
                \(fixture.tokenIDs.count)) — cross-engine render parity broken
                """)
            #expect(swiftIDs.count == fixture.promptTokenCount)

            // Byte-for-byte string parity via decode round-trip: Swift's
            // applyChatTemplate does not expose the rendered string, so the
            // decoded token sequence is compared against the Python-rendered
            // string (special tokens kept).
            if fixture.inputs.api != "render_reader" {
                let decoded = tokenizer.decode(tokens: swiftIDs, skipSpecialTokens: false)
                #expect(
                    decoded == fixture.rendered,
                    """
                    \(fixture.caseName) [\(modelID)]: decoded Swift render is \
                    not byte-identical to the Python-rendered string.
                    python: \(fixture.rendered.debugDescription)
                    swift:  \(decoded.debugDescription)
                    """)
            }

            // Double-BOS tripwire (gemma must be exactly 1 in EVERY case,
            // system prompt or not; qwen 0).
            #expect(
                Self.leadingBOSCount(swiftIDs, bosTokenID: fixture.bosTokenID)
                    == fixture.bosCount,
                Comment(
                    rawValue: "\(fixture.caseName) [\(modelID)]: leading-BOS count "
                        + "changed — double-BOS (or lost-BOS) regression"))
        }
    }

    // MARK: - Conversation constraints: the static table vs the LIVE template

    /// `ExperimentTasks.conversationConstraints` is a static per-family
    /// table (the vendored families are pinned). This test replays the
    /// empirical probes (assistant-first, consecutive same-role) against the
    /// REAL cached tokenizer's chat template, so re-vendoring a family whose
    /// template changed its conversation rules fails HERE, not as a
    /// mid-session refusal (or 400) in the Playground.
    @Test(arguments: fixtureModelIDs)
    func constraintTableMatchesLiveTemplate(modelID: String) async throws {
        guard let snapshot = Self.cachedSnapshot(for: modelID) else {
            print(
                "SKIP GoldenRenderFixtureTests.constraintTableMatchesLiveTemplate"
                    + "(\(modelID)): tokenizer not in local HF cache — the "
                    + "constraint table is NOT verified live for this model")
            return
        }
        let tokenizer = try await AutoTokenizer.from(modelFolder: snapshot)
        let constraints = ExperimentTasks.conversationConstraints(modelID: modelID)

        func renders(_ chat: [Chat.Message]) -> Bool {
            let messages = DefaultMessageGenerator().generate(messages: chat)
            do {
                _ = try tokenizer.applyChatTemplate(
                    messages: messages, tools: nil,
                    additionalContext: ExperimentTasks.qwenContext(
                        modelID: modelID, qwenThinkingEnabled: false))
                return true
            } catch {
                return false
            }
        }

        #expect(
            renders([.user("Q"), .assistant("A"), .user("Q2")]),
            "\(modelID): a plain alternating history must always render")
        #expect(
            renders([.assistant("Seeded reply."), .user("Question?")])
                == !constraints.requiresLeadingUserTurn,
            "\(modelID): requiresLeadingUserTurn drifted from the live template")
        let permissive = !constraints.forbidsConsecutiveSameRole
        #expect(
            renders([.user("Q"), .assistant("A one."), .assistant("A two.")])
                == permissive,
            "\(modelID): forbidsConsecutiveSameRole (assistant) drifted")
        #expect(
            renders([.user("Q one."), .user("Q two.")]) == permissive,
            "\(modelID): forbidsConsecutiveSameRole (user) drifted")
    }

    // MARK: - Known rawCompletion divergence (pinned, not papered over)

    /// The Swift engine does NOT have a true raw-completion path: mlx-swift-lm
    /// routes `UserInput(prompt: .text(...))` through the chat template as a
    /// single user turn (`LLMUserInputProcessor.prepare` →
    /// `MessageGenerator.generate(from:)` → `.text` → `[.user(text)]` →
    /// `applyChatTemplate`), while the Python engine tokenizes the raw string
    /// with tokenizer-default special tokens and no template
    /// (`prompt_render.render`, RAW_COMPLETION). This test pins BOTH current
    /// behaviors so a change on either side fails loudly:
    ///
    /// 1. the pre-tokenization TEXT built by `ExperimentTasks.userInput`
    ///    equals the Python `rendered` string byte-for-byte (system fold +
    ///    Qwen " /no_think" suffix agree);
    /// 2. encoding that text with tokenizer defaults reproduces the Python
    ///    golden ids (pure tokenizer parity);
    /// 3. the ids the Swift engine ACTUALLY feeds the model (chat-templated)
    ///    differ from the golden — the divergence itself. If this ever starts
    ///    matching, the engines have converged: update the fixtures + README.
    @Test(arguments: fixtureModelIDs)
    func rawCompletionDivergence(modelID: String) async throws {
        guard let snapshot = Self.cachedSnapshot(for: modelID) else {
            print(
                "SKIP GoldenRenderFixtureTests.rawCompletionDivergence(\(modelID)): "
                    + "tokenizer not in local HF cache")
            return
        }
        let tokenizer = try await AutoTokenizer.from(modelFolder: snapshot)
        let fixtures = try Self.loadFixtures().filter {
            $0.modelID == modelID && $0.inputs.promptMode == "rawCompletion"
        }
        #expect(!fixtures.isEmpty, "no rawCompletion fixture for \(modelID)")

        for fixture in fixtures {
            let input = ExperimentTasks.userInput(
                prompt: fixture.inputs.prompt ?? "",
                modelID: modelID,
                promptMode: .rawCompletion,
                systemPrompt: fixture.inputs.systemPrompt,
                qwenThinkingEnabled: fixture.inputs.qwenThinkingEnabled ?? false)
            guard case .text(let rawText) = input.prompt else {
                Issue.record(
                    Comment(
                        rawValue: "\(fixture.caseName) [\(modelID)]: rawCompletion "
                            + "should build UserInput.Prompt.text"))
                continue
            }

            // (1) the raw TEXT agrees across engines.
            #expect(
                rawText == fixture.rendered,
                Comment(
                    rawValue: "\(fixture.caseName) [\(modelID)]: rawCompletion "
                        + "pre-tokenization text diverged from the Python render"))

            // (2) tokenizer-level parity on that text (Python's actual ids).
            let rawIDs = tokenizer.encode(text: rawText)  // addSpecialTokens default true
            #expect(
                rawIDs == fixture.tokenIDs,
                Comment(
                    rawValue: "\(fixture.caseName) [\(modelID)]: raw-text "
                        + "tokenization diverged from the Python golden ids"))

            // (3) the pinned divergence: what the Swift engine actually feeds
            // the model is the chat-templated wrap, ≠ the Python raw ids.
            let messages = DefaultMessageGenerator().generate(from: input)
            let liveSwiftIDs = try tokenizer.applyChatTemplate(
                messages: messages, tools: input.tools,
                additionalContext: input.additionalContext)
            #expect(
                liveSwiftIDs != fixture.tokenIDs,
                """
                \(fixture.caseName) [\(modelID)]: the Swift live rawCompletion \
                path now matches the Python raw tokenization — the documented \
                divergence has been reconciled. Update the raw_completion \
                fixtures, the fixture README, and this test to assert parity.
                """)
        }
    }
}
